@Test
void partialSums_reversed() {
    assertEquals(Can.<String>of("a", "b"), Can.<String>empty().add("a").add("b"));
    assertEquals(Can.<String>of("a", "b"), Can.<String>empty().add(0, "b").add(0, "a"));
    final Can<String> all = Can.<String>of("a", "b", "c");
