    view.setValue("64");
    assertEquals(64, primary.getValue());
    assertEquals(64, secondary.getValue());
    assertEquals("64", view.getValue());
    assertEquals(3, primaryChangeCounter.intValue());
    assertEquals(4, secondaryChangeCounter.intValue());
}

@Test
void test() {
    val vList = new _VersionedList<String>();
    assertEquals(0, vList.size());
    assertTrue(vList.isEmpty());
    vList.add("foo");
    assertEquals(1, vList.size());
    assertFalse(vList.isEmpty());
    val snapshot1 = vList.snapshot();
    assertEquals(1, snapshot1.stream().count());
    vList.add("bar");
    val snapshot2 = vList.snapshot();
    assertEquals(2, snapshot2.stream().count());
    assertEquals("foo,bar", snapshot2.stream().collect(Collectors.joining(",")));
    val delta = vList.deltaSince(snapshot1);
    assertEquals(1, delta.stream().count());
    assertEquals("bar", delta.stream().collect(Collectors.joining(",")));
    vList.add("gru");
    val snapshot3 = vList.snapshot();
    assertEquals("foo,bar,gru", snapshot3.stream().collect(Collectors.joining(",")));
    val snapshot4 = vList.deltaSince(snapshot3);
    assertTrue(snapshot4.isEmpty());
}

/**
 * Test method for {@link org.apache.causeway.commons.internal.collections._Arrays#testAnyMatch(T[], T[], java.util.function.BiPredicate)}.
 */
@Test
void testTestAnyMatch() {
    FiniteSpace2.visit(inputSamples, inputSamples, (i, j, a, b) -> {
        if (_NullSafe.size(a) != _NullSafe.size(b)) {
            assertThrows(IllegalArgumentException.class, () -> _Arrays.testAnyMatch(a, b, Objects::equals));
        } else if (_NullSafe.size(a) * _NullSafe.size(b) == 0 || i != j) {
            assertFalse(_Arrays.testAnyMatch(a, b, Objects::equals));
        } else {
            // i==j
            assertEquals(i, j);
            assertTrue(_Arrays.testAnyMatch(a, b, Objects::equals));
        }
    });
    assertTrue(_Arrays.testAnyMatch(new Integer[] { 0, 1, 2, 9 }, new Integer[] { 1, 2, 3, 9 }, Objects::equals));
    assertFalse(_Arrays.testAnyMatch(new Integer[] { 0, 1, 2, 3 }, new Integer[] { 1, 2, 3, 4 }, Objects::equals));
}

