@Test
void invoke_mixin() {
    // given
    val counter1 = bookmarkService.lookup(target1, Counter.class).orElseThrow();
    val interaction = interactionService.currentInteraction().orElseThrow();
    // when
    wrapperFactory.wrapMixinT(Counter_bumpUsingMixin.class, counter1).act();
    // then
    // ... execution log already persisted
    var executionLogEntries = executionLogEntryRepository.findMostRecent();
    assertThat(executionLogEntries).hasSize(1);
    val executionLogEntry = executionLogEntries.get(0);
    assertThat(executionLogEntry).satisfies(e -> assertThat(e.getInteractionId()).isEqualTo(interaction.getInteractionId())).satisfies(e -> assertThat(e.getCompletedAt()).isNotNull()).satisfies(e -> assertThat(e.getDuration()).isNotNull()).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isNotNull()).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isEqualTo("cmdexecauditsess.test.Counter#bumpUsingMixin")).satisfies(e -> assertThat(e.getUsername()).isEqualTo("__system")).satisfies(e -> assertThat(e.getTarget()).isEqualTo(target1)).satisfies(e -> assertThat(e.getTimestamp()).isNotNull()).satisfies(e -> assertThat(e.getType()).isEqualTo(DomainChangeRecord.ChangeType.EXECUTION)).satisfies(e -> assertThat(e.getInteractionDto()).satisfies(dto -> assertThat(dto).isNotNull()).satisfies(dto -> assertThat(dto.getExecution()).isInstanceOf(ActionInvocationDto.class)).satisfies(dto -> assertThat(dto.getExecution().getLogicalMemberIdentifier()).isEqualTo(executionLogEntry.getLogicalMemberIdentifier())));
    // then
    // ... and execution outbox already persisted
    var executionOutboxEntries = executionOutboxEntryRepository.findAll();
    assertThat(executionOutboxEntries).hasSize(1);
    val executionOutboxEntry = executionOutboxEntries.get(0);
    assertThat(executionOutboxEntry).satisfies(e -> assertThat(e.getInteractionId()).isEqualTo(interaction.getInteractionId())).satisfies(e -> assertThat(e.getCompletedAt()).isNotNull()).satisfies(e -> assertThat(e.getDuration()).isNotNull()).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isNotNull()).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isEqualTo("cmdexecauditsess.test.Counter#bumpUsingMixin")).satisfies(e -> assertThat(e.getUsername()).isEqualTo("__system")).satisfies(e -> assertThat(e.getTarget()).isEqualTo(target1)).satisfies(e -> assertThat(e.getTimestamp()).isNotNull()).satisfies(e -> assertThat(e.getType()).isEqualTo(DomainChangeRecord.ChangeType.EXECUTION)).satisfies(e -> assertThat(e.getInteractionDto()).satisfies(dto -> assertThat(dto).isNotNull()).satisfies(dto -> assertThat(dto.getExecution()).isInstanceOf(ActionInvocationDto.class)).satisfies(dto -> assertThat(dto.getExecution().getLogicalMemberIdentifier()).isEqualTo(executionLogEntry.getLogicalMemberIdentifier())));
    // ... but command not yet persisted
    var commandLogEntries = commandLogEntryRepository.findAll();
    assertThat(commandLogEntries).isEmpty();
    // ... and audit entries not yet generated
    var auditTrailEntries = auditTrailEntryRepository.findAll();
    assertThat(auditTrailEntries).isEmpty();
    // when
    // flushes the command and audit trail entries
    interactionService.nextInteraction();
    // then
    // ... command entry created
    commandLogEntries = commandLogEntryRepository.findAll();
    assertThat(commandLogEntries).hasSize(1);
    val commandLogEntry = commandLogEntries.get(0);
    assertThat(commandLogEntry).satisfies(e -> assertThat(e.getInteractionId()).isEqualTo(interaction.getInteractionId())).satisfies(e -> assertThat(e.getCompletedAt()).isNotNull()).satisfies(e -> assertThat(e.getDuration()).isNotNull()).satisfies(e -> assertThat(e.getException()).isEqualTo("")).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isNotNull()).satisfies(e -> assertThat(e.getLogicalMemberIdentifier()).isEqualTo("cmdexecauditsess.test.Counter#bumpUsingMixin")).satisfies(e -> assertThat(e.getUsername()).isEqualTo("__system")).satisfies(e -> assertThat(e.getResult()).isNotNull()).satisfies(e -> assertThat(e.getResultSummary()).isEqualTo("OK")).satisfies(e -> assertThat(e.getReplayState()).isEqualTo(ReplayState.UNDEFINED)).satisfies(e -> assertThat(e.getReplayStateFailureReason()).isNull()).satisfies(e -> assertThat(e.getTarget()).isEqualTo(target1)).satisfies(e -> assertThat(e.getTimestamp()).isNotNull()).satisfies(e -> assertThat(e.getType()).isEqualTo(DomainChangeRecord.ChangeType.COMMAND)).satisfies(e -> assertThat(e.getCommandDto()).satisfies(dto -> assertThat(dto).isNotNull()).satisfies(dto -> assertThat(dto.getMember()).isInstanceOf(ActionDto.class)).satisfies(dto -> assertThat(dto.getMember().getLogicalMemberIdentifier()).isEqualTo(commandLogEntry.getLogicalMemberIdentifier())));
    if (!isJpa()) {
        // and then
        // ... audit trail entry created
        auditTrailEntries = auditTrailEntryRepository.findAll();
        assertThat(auditTrailEntries).hasSize(1);
        var propertyIds = auditTrailEntries.stream().map(AuditTrailEntry::getPropertyId).collect(Collectors.toList());
        assertThat(propertyIds).containsExactly("num");
        var entriesById = auditTrailEntries.stream().collect(Collectors.toMap(AuditTrailEntry::getPropertyId, x -> x));
        assertThat(entriesById.get("num")).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getLogicalMemberIdentifier).isEqualTo("cmdexecauditsess.test.Counter#num")).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getPreValue).isNull()).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getPostValue).isEqualTo("1")).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getInteractionId).isEqualTo(interaction.getInteractionId())).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getSequence).isEqualTo(0)).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getTarget).isEqualTo(target1)).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getTimestamp).isNotNull()).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getType).isEqualTo(DomainChangeRecord.ChangeType.AUDIT_ENTRY)).satisfies(e -> assertThat(e).extracting(AuditTrailEntry::getUsername).isEqualTo("__system"));
    }
}

