    false, arg0Visible -> assertFalse(arg0Visible), arg1Visible -> assertTrue(arg1Visible));
    // disable0PlaceOrder(x): String = "my disable reason-0"
    // disable1PlaceOrder(z): String = "my disable reason-1"
    act.assertParameterUsability(// skip rule checking
    false, arg0Veto -> assertEquals("my disable reason-0", arg0Veto), arg1Veto -> assertEquals("my disable reason-1", arg1Veto));
    // choices0PlaceOrder(x): List.of("my choice")
    act.assertParameterModel(// skip rule checking
    false, pendingArgsWhen -> {
    }, pendingArgsThen -> {
        val actualChoices = pendingArgsThen.getObservableParamChoices(0).getValue().map(ManagedObject::getPojo);
        assertEquals(Can.of("my choice"), actualChoices);
    });
    // autoComplete1PlaceOrder(y, search): List.of("my search arg=" + search)
    act.assertParameterModel(// skip rule checking
    false, pendingArgsWhen -> {
        pendingArgsWhen.getBindableParamSearchArgument(1).setValue("hello");
    }, pendingArgsThen -> {
