void paramRangeA_whenChanging_shouldRenderParamAInvalid() {
    // turn on validation feedback for testing
    pendingArgs.activateValidationFeedback();
    // expected pre condition
    assertEquals(null, uiParamA.getValidationMessage());
    // verify that changing paramRangeA triggers validation change listeners on paramA
    assertDoesIncrement(uiParamA::getValidationUpdateEventCount, () -> uiParamRangeA.simulateChoiceSelect(NumberRange.NEGATIVE.ordinal()));
    // not only verify that paramA is invalid, but also that all pending args were considered
    assertEquals("invalid, element not contained in NEGATIVE got 1, param set [1, -1, -3]", uiParamA.getValidationMessage());
}

