void authenticationStrategyRoundtrip_whenProduction(final String displayName, final Function<String, ICrypt> cryptFactory) {
    val encryptionKey = "any other than FIXED_SALT_FOR_PROTOTYPING";
    val strategy = new DefaultAuthenticationStrategy("cookieKey", cryptFactory.apply(encryptionKey));
    strategy.save("hello", "world", "appendix");
    val data = strategy.load();
    assertNotNull(data);
